import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> [side, price, remaining_qty, seq]
    seq_counter = 0
    trades = []

    def clean_buy():
        while buy_heap:
            _, _, bid = buy_heap[0]
            if bid not in book or book[bid][2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            _, _, sid = sell_heap[0]
            if sid not in book or book[sid][2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid][2] = 0
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                if sid not in book or book[sid][2] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and price < sp:
                    break
                trade_qty = min(remaining, book[sid][2])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                book[sid][2] -= trade_qty
                if book[sid][2] <= 0:
                    heapq.heappop(sell_heap)
                clean_sell()

            if typ == 'limit' and remaining > 0:
                book[oid] = ['buy', price, remaining, seq]
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                if bid not in book or book[bid][2] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and price > bp:
                    break
                trade_qty = min(remaining, book[bid][2])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                book[bid][2] -= trade_qty
                if book[bid][2] <= 0:
                    heapq.heappop(buy_heap)
                clean_buy()

            if typ == 'limit' and remaining > 0:
                book[oid] = ['sell', price, remaining, seq]
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

